    const fa = [0, 1, 2, 3, 4].map(i => (((nu.fa0[i] + nu.fa1[i] * t) % 1296000.0) + 0) * ASEC);
    const f1 = [0, 1, 2, 3, 4].map(i => nu.fa1[i] * ASEC);
