      const a = g[0] * fa[0] + g[1] * fa[1] + g[2] * fa[2] + g[3] * fa[3] + g[4] * fa[4];
      const da = g[0] * f1[0] + g[1] * f1[1] + g[2] * f1[2] + g[3] * f1[3] + g[4] * f1[4];
      const s = Math.sin(a), co = Math.cos(a);
      dpsi += (L[0] + L[1] * t) * s + L[2] * co;
      deps += (O[0] + O[1] * t) * co + O[2] * s;
