const pmod = (a, m) => { const r = a % m; return r < 0 ? r + m : r; };   // Python a % m for m > 0

const SUN = 0, MOON = 1, MERCURY = 2, VENUS = 3, MARS = 4, JUPITER = 5, SATURN = 6, URANUS = 7,
  NEPTUNE = 8, PLUTO = 9, TRUE_NODE = 11, MEAN_APOG = 12, CHIRON = 15, ECL_NUT = -1;
const FLG_EQUATORIAL = 2048, FLG_SIDEREAL = 65536;
