// ---------------------------------------------------------------- calendar
function julday(y, m, d, h = 12.0) {
  if (m <= 2) { y -= 1; m += 12; }
  const a = Math.floor(y / 100);
  const b = 2 - a + Math.floor(a / 4);
  return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (m + 1)) + d + b - 1524.5 + h / 24.0;
}

function revjul(jd) {
  const z = Math.floor(jd + 0.5);
  const f = jd + 0.5 - z;
  const al = Math.floor((z - 1867216.25) / 36524.25);
  const a = z + 1 + al - Math.floor(al / 4);
  const b = a + 1524;
  const c = Math.floor((b - 122.1) / 365.25);
  const d = Math.floor(365.25 * c);
  const e = Math.floor((b - d) / 30.6001);
  const day = b - d - Math.floor(30.6001 * e);
  const m = e < 14 ? e - 1 : e - 13;
  const y = m > 2 ? c - 4716 : c - 4715;
  return [y, m, day, f * 24.0];
}

function ttFromUT(jdUT) { return eph().ttFromUT(jdUT); }

// ---------------------------------------------------------------- formulas
function nut(tt) { return eph().nutation(tt); }

function pA(tt) {
  const T = (tt - 2451545.0) / 36525.0;
  return (5028.796195 * T + 1.1054348 * T ** 2 + 0.00007964 * T ** 3 - 0.000023857 * T ** 4 - 0.0000000383 * T ** 5) / 3600.0;
}
function getAyanamsa(tt) { return LAHIRI_A0 + pA(tt) - pA(LAHIRI_T0); }
function getAyanamsaUT(jdUT) { return getAyanamsa(ttFromUT(jdUT)); }

function lilith(tt, dpsi) {
  const T = (tt - 2451545.0) / 36525.0;
  const w = 83.3532465 + 4069.0137287 * T - 0.0103200 * T ** 2 - T ** 3 / 80053 + T ** 4 / 18999000 + 180.0;
  const om = 125.0445479 - 1934.1362891 * T + 0.0020754 * T ** 2 + T ** 3 / 467441 - T ** 4 / 60616000;
  const i = 5.1453964 * RAD, u = (w - om) * RAD;
  const lon = om + Math.atan2(Math.cos(i) * Math.sin(u), Math.cos(u)) * DEG;
  const lat = Math.asin(Math.sin(i) * Math.sin(u)) * DEG;
  return [pmod(lon + dpsi * DEG, 360), lat];
}

function ecl2eq(lon, lat, eps) {
  const l = lon * RAD, b = lat * RAD;
  const ra = Math.atan2(Math.sin(l) * Math.cos(eps) - Math.tan(b) * Math.sin(eps), Math.cos(l));
  const dec = Math.asin(Math.sin(b) * Math.cos(eps) + Math.cos(b) * Math.sin(eps) * Math.sin(l));
  return [pmod(ra * DEG, 360), dec * DEG];
}

/** Like swe.calc: argument JD TT → [lon, lat, dist, lon speed] (degrees, au, deg/day). */
function calc(tt, pid, flags = 0) {
  const E = eph();
  const nu = nut(tt);
  const em = E.constructor.meanObliquity(tt);
  if (pid === ECL_NUT) return [(em + nu[1]) * DEG, em * DEG, nu[0] * DEG, nu[1] * DEG];
  let lon, lat, dist, spd;
  if (pid === MEAN_APOG) {
    [lon, lat] = lilith(tt, nu[0]);
    const lon2 = lilith(tt + 0.5, nu[0])[0], lon1 = lilith(tt - 0.5, nu[0])[0];
    spd = pmod(lon2 - lon1 + 180, 360) - 180; dist = 0.0027106;
  } else {
    const p = E.position(NAMES[pid], tt, nu);
    lon = p[0] * DEG; lat = p[1] * DEG; dist = p[2]; spd = p[3] * DEG;
  }
  if (flags & FLG_EQUATORIAL) {
    const [ra, dec] = ecl2eq(lon, lat, em + nu[1]);
    return [ra, dec, dist, spd];
  }
  if (flags & FLG_SIDEREAL) lon = pmod(lon - nu[0] * DEG - getAyanamsa(tt), 360);
  return [lon, lat, dist, spd];
}
function calcUT(jdUT, pid, flags = 0) { return calc(ttFromUT(jdUT), pid, flags); }

function gast(jdUT) {
  const E = eph();
  const tt = ttFromUT(jdUT);
  const T = (tt - 2451545.0) / 36525.0;
  const du = jdUT - 2451545.0;
  const era = 2 * Math.PI * pmod(0.7790572732640 + 0.00273781191135448 * du + du, 1.0);
  const gmst = era + (0.014506 + 4612.156534 * T + 1.3915817 * T ** 2 - 0.00000044 * T ** 3
    - 0.000029956 * T ** 4 - 0.0000000368 * T ** 5) * ASEC_;
  const nu = nut(tt);
  const eps = E.constructor.meanObliquity(tt) + nu[1];
  return [pmod(gmst + nu[0] * Math.cos(eps), 2 * Math.PI), eps];
}

/** Placidus; Porphyry where Placidus is undefined (|φ| ≥ 90° − ε), like Swiss Ephemeris. → {cusps[12], asc, mc} */
function housesP(jdUT, lat, lon) {
  const [g, eps] = gast(jdUT);
  const ramc = pmod(g + lon * RAD, 2 * Math.PI);
  const phi = lat * RAD;
  const mc = pmod(Math.atan2(Math.sin(ramc), Math.cos(ramc) * Math.cos(eps)) * DEG, 360);
  const asc = pmod(Math.atan2(Math.cos(ramc), -(Math.sin(ramc) * Math.cos(eps) + Math.tan(phi) * Math.sin(eps))) * DEG, 360);
  const c = new Array(13).fill(0);
  c[1] = asc; c[10] = mc; c[4] = pmod(mc + 180, 360); c[7] = pmod(asc + 180, 360);
  if (Math.abs(lat) < 90 - eps * DEG) {
    const cusp = (f, upper) => {
      let ra = ramc + (upper ? f * Math.PI / 2 : Math.PI - (1 - f) * Math.PI / 2);
      for (let it = 0; it < 100; it++) {
        const lam = Math.atan2(Math.sin(ra), Math.cos(ra) * Math.cos(eps));
        const dec = Math.asin(Math.sin(eps) * Math.sin(lam));
        const ad = Math.asin(Math.max(-1.0, Math.min(1.0, Math.tan(phi) * Math.tan(dec))));
        const sda = Math.PI / 2 + ad;
        const nw = upper ? ramc + f * sda : ramc + Math.PI - f * (Math.PI - sda);
        if (Math.abs(nw - ra) < 1e-13) { ra = nw; break; }
        ra = nw;
      }
      return pmod(Math.atan2(Math.sin(ra), Math.cos(ra) * Math.cos(eps)) * DEG, 360);
    };
    c[11] = cusp(1 / 3, true); c[12] = cusp(2 / 3, true);
    c[3] = cusp(1 / 3, false); c[2] = cusp(2 / 3, false);
  } else {
    const q1 = pmod(asc - mc, 360), q2 = pmod(mc + 180 - asc, 360);
    c[11] = pmod(mc + q1 / 3, 360); c[12] = pmod(mc + 2 * q1 / 3, 360);
    c[2] = pmod(asc + q2 / 3, 360); c[3] = pmod(asc + 2 * q2 / 3, 360);
  }
  for (const h of [5, 6]) c[h] = pmod(c[h + 6] + 180, 360);
  for (const h of [8, 9]) c[h] = pmod(c[h - 6] + 180, 360);
  return { cusps: c.slice(1), asc, mc };
}

/** Equation of time (true − mean solar), days. Meeus 28.3. */
function timeEqu(jdUT) {
  const E = eph();
  const tt = ttFromUT(jdUT);
  const tau = (tt - 2451545.0) / 365250.0;
  const L0 = pmod(280.4664567 + 360007.6982779 * tau + 0.03032028 * tau ** 2 + tau ** 3 / 49931
    - tau ** 4 / 15300 - tau ** 5 / 2e6, 360);
  const nu = nut(tt);
  const [lon, lat] = E.position('sun', tt, nu);
  const eps = E.constructor.meanObliquity(tt) + nu[1];
  const ra = pmod(Math.atan2(Math.sin(lon) * Math.cos(eps) - Math.tan(lat) * Math.sin(eps), Math.cos(lon)) * DEG, 360);
  const e = pmod(L0 - 0.0057183 - ra + nu[0] * DEG * Math.cos(eps) + 180, 360) - 180;
  return e / 360.0;
}

/** First moment (UT) after jdUT when the apparent longitude of the Sun equals x2cross. */
function solcrossUT(x2cross, jdUT) {
  const lon = calcUT(jdUT, SUN);
  let t = jdUT + pmod(x2cross - lon[0], 360) / 0.9856;
  for (let it = 0; it < 30; it++) {
    const r = calcUT(t, SUN);
    const d = pmod(x2cross - r[0] + 180, 360) - 180;
    t += d / r[3];
    if (Math.abs(d) < 1e-10) break;
  }
  return t;
}

