const digits = n => String(n).split('').reduce((s, c) => s + +c, 0);
function red22(n) { while (n > 22) n = digits(n); return n; }
function red9(n) { while (n > 9) n = digits(n); return n; }
function redMaster(n) { while (n > 9 && n !== 11 && n !== 22 && n !== 33) n = digits(n); return n; }
function chain(n) { const out = [n]; while (n > 9 && !(n === 11 || n === 22 || n === 33)) { n = digits(n); out.push(n); } return out; }
function jdn(y, m, d) {
  const a = Math.floor((14 - m) / 12), yy = y + 4800 - a, mm = m + 12 * a - 3;
  return d + Math.floor((153 * mm + 2) / 5) + 365 * yy + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400) - 32045;
}
const signIdx = lon => Math.floor(pmod(lon, 360) / 30);
function pad2(n) { return String(n).padStart(2, '0'); }
function isoOfJdn(J) {                      // JDN → 'YYYY-MM-DD' (proleptic Gregorian)
  const [y, m, d] = revjul(J);            // JDN (noon) → same civil date
  return `${y}-${pad2(m)}-${pad2(d)}`;
}
/** chart.py _dt(jd): UTC date of a JD (datetime(y, m, d) + hours, truncated to the day). */
function dateOfJd(jd) {
  const [y, m, d, h] = revjul(jd);
  const ms = Math.round(h * 3600e6) / 1e3;     // timedelta keeps microseconds
  const t = Date.UTC(y, m - 1, d) + ms;
  return new Date(Math.floor(t / 86400000) * 86400000).toISOString().slice(0, 10);
}

// ---------------------------------------------------------------- bazi
const sunLonUT = jd => calcUT(jd, SUN)[0];

function pillarsCore(y, m, d, hh, mi, lonE, tz) {
  const jd = julday(y, m, d, hh + mi / 60 - tz);
  const ut = hh + mi / 60 - tz;
  const eot = timeEqu(jd) * 1440;
  let solar = ut + lonE / 15 + eot / 60, shift = 0;
  while (solar < 0) { solar += 24; shift -= 1; }
  while (solar >= 24) { solar -= 24; shift += 1; }
  let J = jdn(y, m, d) + shift;
  if (solar >= 23) J += 1;                                   // B18: bazi day changes at 23:00 true solar
  const idx = pmod(J + 49, 60);
  const dayG = GAN[idx % 10], dayZ = ZHI[idx % 12];
  const hzI = Math.floor((solar + 1) / 2) % 12;
  const dayNote = Math.abs(solar - 23) <= 0.25;
  const start = { '甲': '甲', '己': '甲', '乙': '丙', '庚': '丙', '丙': '戊', '辛': '戊', '丁': '庚', '壬': '庚', '戊': '壬', '癸': '壬' }[dayG];
  const hourG = GAN[(GAN.indexOf(start) + hzI) % 10], hourZ = ZHI[hzI];
  const L = sunLonUT(jd);
  const by = (m <= 2 && !(315 <= L && L < 360)) ? y - 1 : y;
  const yearG = GAN[pmod(by - 4, 10)], yearZ = ZHI[pmod(by - 4, 12)];
  const monthZ = ZHI[(Math.floor(pmod(L - 315, 360) / 30) + 2) % 12];
  const monthG = GAN[(GAN.indexOf(yearG) * 2 + pmod(ZHI.indexOf(monthZ) - 2, 12) + 2) % 10];
  return { hour: hourG + hourZ, day: dayG + dayZ, month: monthG + monthZ, year: yearG + yearZ, dm: dayG,
    solarYear: by, sunLon: L, jd, solar, solarTime: pad2(Math.floor(solar)) + ':' + pad2(Math.floor((solar % 1) * 60)),
    eot, dayNote, hzI };
}

function jieMoments(jd) {
  const L = sunLonUT(jd);
  const k = Math.floor(pmod(L - 315, 360) / 30);
  const start = pmod(315 + 30 * k, 360), nxt = pmod(start + 30, 360);
  let prev = solcrossUT(start, jd - 40);
  if (prev > jd) prev = solcrossUT(start, jd - 70);
  return [prev, solcrossUT(nxt, jd)];
}

function luckCore(p, male, by, bm, bd, ry, rm, rd) {
  const fwd = (GAN.indexOf(p.year[0]) % 2 === 0) === male;
  const [prev, next] = jieMoments(p.jd);
  const days = fwd ? next - p.jd : p.jd - prev;
  const start = days / 3.0;
  const gi = GAN.indexOf(p.month[0]), zi = ZHI.indexOf(p.month[1]);
  const bJ = jdn(by, bm, bd);
  const ageNow = (jdn(ry, rm, rd) - bJ) / 365.2422;
  const list = [];
  let current = -1;
  for (let k = 1; k <= 8; k++) {
    const step = fwd ? k : -k;
    const gz = GAN[pmod(gi + step, 10)] + ZHI[pmod(zi + step, 12)];
    const a0 = start + (k - 1) * 10;
    list.push({ gz, a0, from: isoOfJdn(bJ + Math.floor(a0 * 365.2422)), to: isoOfJdn(bJ + Math.floor((a0 + 10) * 365.2422)) });
    if (a0 <= ageNow && ageNow < a0 + 10) current = k - 1;
  }
  return { fwd, start, list, current, ageNow, jie: [prev, next] };
}

// ---------------------------------------------------------------- numerology (chart.py numerology, B14)
const RU_ALPHABET = 'АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ', RU_VOWELS = 'АЕЁИОУЫЭЮЯ';
const UK_ALPHABET = 'АБВГҐДЕЄЖЗИІЇЙКЛМНОПРСТУФХЦЧШЩЬЮЯ', UK_VOWELS = 'АЕЄИІЇОУЮЯ';
const KARMIC_DEBT = [13, 14, 16, 19];

function nameNumbers(fullName, lang) {
  const letters = [...fullName.toUpperCase()].filter(c => /\p{L}/u.test(c));
  if (!lang) lang = letters.some(c => 'ҐЄІЇ'.includes(c)) ? 'uk' : 'ru';
  const alpha = lang === 'uk' ? UK_ALPHABET : RU_ALPHABET, vowels = lang === 'uk' ? UK_VOWELS : RU_VOWELS;
  const bad = [...new Set(letters.filter(c => !alpha.includes(c)))].sort();
  if (bad.length) throw new Error(`letters outside the ${lang === 'uk' ? 'Ukrainian' : 'Russian'} table: ${bad.join('')} — write the name as in the document`);
  if (!letters.length) throw new Error('empty name');
  const val = c => alpha.indexOf(c) % 9 + 1;
  const vals = letters.map(val), vow = letters.filter(c => vowels.includes(c)).map(val), con = letters.filter(c => !vowels.includes(c)).map(val);
  const res = { full_name: fullName.split(/\s+/).filter(Boolean).join(' '), table: lang };
  for (const [key, arr] of [['expression', vals], ['soul', vow], ['personality', con]]) {
    const ch = arr.length ? chain(arr.reduce((a, b) => a + b, 0)) : [null];
    res[key] = ch[ch.length - 1]; res[key + '_chain'] = ch;
  }
  res.missing_digits = [1, 2, 3, 4, 5, 6, 7, 8, 9].filter(k => !vals.includes(k));
  return res;
}

function personalMonths(d, m, year) {
  const ly = redMaster(digits(d) + digits(m) + digits(year));
  const out = {};
  for (let k = 1; k <= 12; k++) out[`${year}-${pad2(k)}`] = red9(ly + k);
  return out;
}

function numerologyCore(y, m, d, ry, rmon, name, lang) {
  const lpChain = chain(digits(`${pad2(d)}${pad2(m)}${y}`));
  const lp = lpChain[lpChain.length - 1];
  const rd = redMaster(d), rm = redMaster(m), ryr = redMaster(digits(y));
  const p1 = redMaster(rm + rd), p2 = redMaster(rd + ryr), p3 = redMaster(p1 + p2), p4 = redMaster(rm + ryr);
  const end1 = 36 - (lp < 10 ? lp : red9(lp));
  const cm = red9(m), cd = red9(d), cy = red9(digits(y));
  const c1 = Math.abs(cm - cd), c2 = Math.abs(cd - cy);
  const months = { ...personalMonths(d, m, ry), ...personalMonths(d, m, ry + 1) };
  const tests = [];
  if (KARMIC_DEBT.includes(d)) tests.push({ number: d, where: 'день рождения' });
  for (const x of lpChain.slice(0, -1)) if (KARMIC_DEBT.includes(x)) tests.push({ number: x, where: 'жизненный путь' });
  let nm = null;
  if (name) {
    nm = nameNumbers(name, lang);
    for (const [key, gen] of [['expression', 'выражения'], ['soul', 'души'], ['personality', 'личности']])
      for (const x of nm[key + '_chain'].slice(0, -1)) if (KARMIC_DEBT.includes(x)) tests.push({ number: x, where: 'число ' + gen });
  }
  const pm = `${ry}-${pad2(rmon)}`;
  return {
    life_path: lp, life_path_chain: lpChain, day_power: redMaster(d),
    personal_year: { [ry]: redMaster(digits(d) + digits(m) + digits(ry)) },
    personal_month: { [pm]: months[pm] },
    personal_months: months,
    pinnacles: [{ value: p1, ages: `0–${end1}` }, { value: p2, ages: `${end1 + 1}–${end1 + 9}` },
      { value: p3, ages: `${end1 + 10}–${end1 + 18}` }, { value: p4, ages: `${end1 + 19}+` }],
    challenges: { first: c1, second: c2, main: Math.abs(c1 - c2), fourth: Math.abs(cm - cy) },
    karmic_tests: tests,
    name: nm,
  };
}

// ---------------------------------------------------------------- tzolkin (Dreamspell), gua
function kinDreamspell(y, m, d) {
  const anchor = (m > 7 || (m === 7 && d >= 26)) ? y : y - 1;
  const kin0 = pmod(34 + (anchor - 1987) * 105, 260);
  const a = jdn(anchor, 7, 26), t = jdn(y, m, d);
  let days = t - a;
  for (let yy = anchor; yy <= y; yy++) {
    const leap = (yy % 4 === 0 && yy % 100 !== 0) || yy % 400 === 0;
    if (leap) { const f = jdn(yy, 2, 29); if (a < f && f <= t) days -= 1; }
  }
  const kin = pmod(kin0 + days - 1, 260) + 1;
  return { kin, tone: (kin - 1) % 13 + 1, seal: (kin - 1) % 20 + 1 };
}

function guaCore(solarYear, female) {
  const Y = red9(digits(solarYear));
  let g = female ? 4 + Y : 11 - Y;
  g = g > 9 ? red9(g) : g;
  if (g === 5) g = female ? 8 : 2;
  return g;
}

// ---------------------------------------------------------------- natal
// Selena by P. Globa: uniform motion, full circle in 7 years; epoch 1990-01-01 0h UT = 88°03′ (chart.py)
const SELENA_EPOCH = 2447892.5, SELENA_LON0 = 88 + 3 / 60, SELENA_PERIOD = 7 * 365.25;
const selenaLon = jd => pmod(SELENA_LON0 + 360.0 * (jd - SELENA_EPOCH) / SELENA_PERIOD, 360);

const NATAL_PL = [['Солнце', SUN], ['Луна', MOON], ['Меркурий', MERCURY], ['Венера', VENUS], ['Марс', MARS],
  ['Юпитер', JUPITER], ['Сатурн', SATURN], ['Уран', URANUS], ['Нептун', NEPTUNE], ['Плутон', PLUTO],
  ['Лилит', MEAN_APOG], ['Хирон', CHIRON]];

function houseOfLon(cusps, l) {
  for (let i = 0; i < 12; i++) {
    const a = cusps[i], b = cusps[(i + 1) % 12];
    if ((a < b && a <= l && l < b) || (a > b && (l >= a || l < b))) return i + 1;
  }
  return null;
}

function nakOf(l, ayan) {
  const s = pmod(l - ayan, 360);
  const i = Math.floor(s / (360 / 27));
  return { index: i, pada: Math.floor(pmod(s, 360 / 27) / (360 / 108)) + 1, sid: s };
}

function natalCore(jd, lat, lon) {
  const hs = housesP(jd, lat, lon);
  const lons = {}, retro = {}, decl = {}, speed = {};
  for (const [n, pid] of NATAL_PL) {
    const r = calcUT(jd, pid), eq = calcUT(jd, pid, FLG_EQUATORIAL);
    lons[n] = r[0]; retro[n] = r[3] < 0; decl[n] = eq[1]; speed[n] = r[3];
  }
  const node = calcUT(jd, TRUE_NODE)[0];
  lons['Северный узел'] = node;
  lons['Южный узел'] = pmod(node + 180, 360);
  lons['Селена'] = selenaLon(jd);
  const eps = calcUT(jd, ECL_NUT)[0];
  const ayan = getAyanamsaUT(jd);
  return { hs, lons, retro, decl, speed, eps, ayan };
}

