function hdActivation(lon) {
  const pos = pmod(lon + HD_WHEEL_OFFSET, 360.0);
  const i = Math.floor(pos / 5.625);
  let w = pos - i * 5.625;
  const line = Math.floor(w / 0.9375); w -= line * 0.9375;
  const color = Math.floor(w / 0.15625); w -= color * 0.15625;
  const tone = Math.floor(w / (0.15625 / 6)); w -= tone * (0.15625 / 6);
  const base = Math.floor(w / (0.15625 / 30));
  return { gate: HD_GATE_ORDER[i], line: line + 1, color: color + 1, tone: tone + 1, base: Math.min(base, 4) + 1, lon };
}

function hdDesignJd(jd) {
  const target = pmod(sunLonUT(jd) - HD_DESIGN_ARC, 360);
  let t = solcrossUT(target, jd - 100);
  for (let it = 0; it < 5; it++) {
    const r = calcUT(t, SUN);
    const diff = pmod(target - r[0] + 180, 360) - 180;
    if (Math.abs(diff) < 1e-9) break;
    t += diff / r[3];
  }
  if (!(jd - 95 < t && t < jd - 84)) throw new Error('design date outside the 84–95 day window');
  return t;
}

function hdActivations(jd) {
  const out = {};
  for (const [name, pid] of HD_PLANETS) {
    let lon;
    if (name === 'Земля') lon = pmod(calcUT(jd, SUN)[0] + 180, 360);
    else if (name === 'Южный узел') lon = pmod(calcUT(jd, TRUE_NODE)[0] + 180, 360);
    else lon = calcUT(jd, pid)[0];
    out[name] = hdActivation(lon);
  }
  return out;
}

function hdConnected(adj, a, targets) {
  if (!adj[a]) return false;
  const stack = [a], seen = new Set();
  while (stack.length) {
    const x = stack.pop();
    if (targets.includes(x)) return true;
    if (seen.has(x)) continue;
    seen.add(x);
    for (const y of adj[x]) if (!seen.has(y)) stack.push(y);
  }
  return false;
}

function humanDesignCore(jd) {
  const djd = hdDesignJd(jd);
  const pers = hdActivations(jd), des = hdActivations(djd);
  const gates = new Set([...Object.values(pers), ...Object.values(des)].map(a => a.gate));
  const channels = HD_CHANNELS.filter(c => gates.has(c[0]) && gates.has(c[1]));
  const defined = new Set(channels.flatMap(c => [c[2], c[3]]));
  const adj = {};
  for (const c of defined) adj[c] = new Set();
  for (const [, , ca, cb] of channels) { adj[ca].add(cb); adj[cb].add(ca); }
  const seen = new Set(), comps = [];
  for (const c of HD_CENTERS) {
    if (!defined.has(c) || seen.has(c)) continue;
    const stack = [c], comp = new Set();
    while (stack.length) {
      const x = stack.pop();
      if (comp.has(x)) continue;
      comp.add(x);
      for (const y of adj[x]) if (!comp.has(y)) stack.push(y);
    }
    for (const x of comp) seen.add(x);
    comps.push(comp);
  }
  const motorThroat = HD_MOTORS.filter(m => defined.has(m)).some(m => hdConnected(adj, m, ['Горло']));
  let type, strategy;
  if (!defined.size) { type = 'Рефлектор'; strategy = 'ждать лунный цикл (около 28 дней)'; }
  else if (defined.has('Сакрал')) { type = motorThroat ? 'Манифестирующий Генератор' : 'Генератор'; strategy = 'отвечать (ждать, на что откликнется сакрал)'; }
  else if (motorThroat) { type = 'Манифестор'; strategy = 'информировать перед действием'; }
  else { type = 'Проектор'; strategy = 'ждать приглашения'; }
  let authority;
  if (!defined.size) authority = 'лунный';
  else if (defined.has('Солнечное сплетение')) authority = 'эмоциональный';
  else if (defined.has('Сакрал')) authority = 'сакральный';
  else if (defined.has('Селезёнка')) authority = 'селезёночный';
  else if (defined.has('Эго')) authority = adj['Эго'].has('Горло') ? 'эго-манифестированный' : 'эго-проецируемый';
  else if (defined.has('G') && hdConnected(adj, 'G', ['Горло'])) authority = 'самопроецируемый';
  else authority = 'ментальный/средовой (нет внутреннего авторитета)';
  const definition = ['нет (Рефлектор)', 'Single', 'Split', 'Triple Split', 'Quadruple Split'][comps.length];
  const ps = pers['Солнце'], ds = des['Солнце'];
  const profile = `${ps.line}/${ds.line}`;
  let angle, name;
  if (HD_RIGHT.includes(profile)) { angle = 'правый угол'; name = 'Right Angle Cross of ' + HD_CROSS_RIGHT[ps.gate]; }
  else if (HD_JUXTA.includes(profile)) { angle = 'джакстапозиция'; name = 'Juxtaposition Cross of ' + HD_CROSS_JUXTA[ps.gate]; }
  else { angle = 'левый угол'; name = 'Left Angle Cross of ' + HD_CROSS_LEFT[ps.gate]; }
  const pn = pers['Северный узел'], dn = des['Северный узел'];
  const LR = a => (a.tone <= 3 ? 'L' : 'R');
  const [y, mo, d, h] = revjul(djd);
  let sec = pyRound(h * 3600), dd = [y, mo, d];
  if (sec >= 86400) { dd = revjul(djd + 0.5 / 86400).slice(0, 3); sec -= 86400; }
  const clean = o => Object.fromEntries(Object.entries(o).map(([k, a]) => [k, { gate: a.gate, line: a.line, color: a.color, tone: a.tone, base: a.base, lon: +a.lon.toFixed(4) }]));
  return {
    design_utc: `${dd[0]}-${pad2(dd[1])}-${pad2(dd[2])} ${pad2(Math.floor(sec / 3600))}:${pad2(Math.floor(sec % 3600 / 60))}:${pad2(sec % 60)}`,
    design_jd: +djd.toFixed(6),
    type, strategy, authority, definition, profile,
    cross: { angle, name, gates: `${ps.gate}/${pers['Земля'].gate} | ${ds.gate}/${des['Земля'].gate}` },
    channels: channels.map(([a, b]) => `${Math.min(a, b)}-${Math.max(a, b)}`),
    defined_centers: HD_CENTERS.filter(c => defined.has(c)),
    open_centers: HD_CENTERS.filter(c => !defined.has(c)),
    variables: { code: 'P' + LR(ps) + LR(pn) + ' D' + LR(ds) + LR(dn),
      motivation: HD_MOTIVATION[ps.color], cognition: HD_COGNITION[ds.tone], determination: HD_DETERMINATION[ds.color],
      environment: HD_ENVIRONMENT[dn.color], view: HD_VIEW[pn.color] },
    personality: clean(pers), design: clean(des),
    _raw: { pers, des, djd },
  };
}

// Python round(): half to even on the binary value
function pyRound(x) {
  const r = Math.round(x);
  return (Math.abs(x % 1) === 0.5 && r % 2 !== 0) ? r - 1 : r;
}

// ---------------------------------------------------------------- Vimshottari (chart.py B13)
const DASHA = [['Кету', 7], ['Венера', 20], ['Солнце', 6], ['Луна', 10], ['Марс', 7], ['Раху', 18], ['Юпитер', 16], ['Сатурн', 19], ['Меркурий', 17]];
const DASHA_YEAR = 365.25;

function vimshottariCore(jdB, tRef) {
  const moon = calcUT(jdB, MOON, FLG_SIDEREAL)[0];
  const span = 360 / 27;
  const i = Math.floor(moon / span);
  const frac = pmod(moon, span) / span;
  const lord = i % 9, years = DASHA[lord][1];
  const mdStart = jdB - frac * years * DASHA_YEAR;
  const mds = [];
  let t = mdStart, k = lord;
  while (t < jdB + 120 * DASHA_YEAR) {
    const [nm, y] = DASHA[k % 9];
    mds.push({ lord: nm, years: y, s: t, e: t + y * DASHA_YEAR });
    t += y * DASHA_YEAR; k += 1;
  }
  const idxOf = nm => DASHA.findIndex(x => x[0] === nm);
  const antars = md => {
    const out = []; let s = md.s; const idx = idxOf(md.lord);
    for (let j = 0; j < 9; j++) { const [nm, y] = DASHA[(idx + j) % 9]; const dur = md.years * y / 120 * DASHA_YEAR; out.push({ lord: nm, s, e: s + dur }); s += dur; }
    return out;
  };
  const pratyantars = (mdLord, ad) => {
    const out = []; let s = ad.s; const idx = idxOf(ad.lord);
    const mdY = DASHA[idxOf(mdLord)][1], adY = DASHA[idxOf(ad.lord)][1];
    for (let j = 0; j < 9; j++) { const [nm, y] = DASHA[(idx + j) % 9]; const dur = mdY * adY * y / 14400 * DASHA_YEAR; out.push({ lord: nm, s, e: s + dur }); s += dur; }
    return out;
  };
  const curI = mds.findIndex(md => md.s <= tRef && tRef < md.e);
  if (curI < 0 || curI + 1 >= mds.length) return null;       // reference date outside birth … +120 years
  const curAd = antars(mds[curI]), nxtAd = antars(mds[curI + 1]);
  const curA = curAd.find(a => a.s <= tRef && tRef < a.e);
  const curPads = pratyantars(mds[curI].lord, curA);
  const curP = curPads.find(p => p.s <= tRef && tRef < p.e);
  const fmt = (x, from) => ({ lord: x.lord, from: dateOfJd(from ?? x.s), to: dateOfJd(x.e) });
  const fmtMd = md => ({ ...fmt(md, Math.max(md.s, jdB)), years: md.years });
  return {
    moon_sid: +moon.toFixed(4), nak_index: i, lord: DASHA[lord][0], passed: +frac.toFixed(6),
    balance_years: +((1 - frac) * years).toFixed(4),
    mahadashas: mds.map(fmtMd),
    current: { maha: fmtMd(mds[curI]), antar: fmt(curA), pratyantar: fmt(curP) },
    antars_current: curAd.map(a => fmt(a)), antars_next: nxtAd.map(a => fmt(a)),
    pratyantars_current: curPads.map(p => fmt(p)),
    _edges: [mds[curI].s, mds[curI].e, curA.s, curA.e, curP.s, curP.e],
  };
}

