/** Chart name: dayPillar = '戊寅' (stem + branch), kin 1..260 (Dreamspell), sunSign — tropical sign of the Sun or null. */
function chartName(dayPillar, kin, sunSign) {
  const stem = dayPillar[0], branch = dayPillar[1];
  const bi = NAME_BRANCHES.indexOf(branch);
  const animal = NAME_ANIMALS[bi];
  const sealNo = (kin - 1) % 20 + 1;
  const role = NAME_ROLE[sealNo - 1], seal = NAME_SEAL_CORE[sealNo - 1];
  const adj = NAME_ELEMENT[stem][NAME_FEMININE.includes(animal) ? 1 : 0];
  const sp = seal.indexOf(' ');
  const plain = sp >= 0 ? seal.slice(sp + 1) : seal;   // without the colour word
  let sub = `${adj} ${animal} · ${plain}`;
  if (sunSign) sub += ` · ${sunSign}`;
  return {
    'имя': `${animal}-${role}`,
    'подпись': sub,
    'действие': NAME_ACTION[sealNo - 1],
    'животное': animal, 'ветвь дня': branch,
    'стихия дня': adj, 'ствол дня': stem,
    'печать': seal, 'номер печати': sealNo, 'роль печати': role,
    'картинки': { 'животное': NAME_PIC[bi], 'печать': 'seal_' + String(sealNo).padStart(2, '0') },
  };
}

