// ---- public API: engine/src/api.js ----
// ---------------------------------------------------------------------------------------------
// Astrogramm engine — public API. Builds contract `chart.json/1` (BACKEND-PLAN §2.3) from core.js,
// a port of the reference core skills/astrogramm-core/chart.py on the same tables (B22: JPL DE440s →
// skills/astrogramm-ephem/v1). Parity with the reference is enforced by engine/tests/parity.py.
//
//   import { useTables, prepare, chartJson } from './astrogramm-engine.js';
//   useTables(indexJson, k => arrayBufferOfChunk(k));   // loader may be sync (Node, bundle) or async (fetch)
//   await prepare(input);                                // loads only the chunks this chart needs (birth + now)
//   const chart = chartJson(input);                      // synchronous once the chunks are in memory
// ---------------------------------------------------------------------------------------------

export const ENGINE_VERSION = '3.0.0-b1.3';
export const CORE_REF = '3.0 (ASTRO_EPH=table)';
export const SOURCE = 'данные NASA JPL, собственные таблицы Astrogramm';

// Border widths. A discrete value closer than this to its boundary is reported in `borders`; the UI says
// "on the border, depends on the exact time" instead of a confident value. Every width must exceed the worst
// engine ↔ core error measured by the parity test (now ≈ 1e-9°: same tables, same formulas); the widths are
// product choices (sensitivity to the birth time), kept from step 1 so the UI does not change behaviour.
export const BORDER = {
  planetDeg: 0.04,      // sign / nakshatra / OOB of a body
  moonNakDeg: 0.03,     // nakshatra of the Moon (sidereal) — also the Vimshottari lord
  ascDeg: 0.10,         // sign of the Ascendant / MC, house of a body on a cusp
  hourMin: 2,           // true-solar time vs. start of a Chinese double hour
  jieMin: 30,           // birth moment vs. solar term (month pillar, Lichun → year pillar)
  luckYears: 0.03,      // reference date vs. change of the luck pillar (≈ 11 days)
  hdDeg: 0.01,          // HD gate / line edge of an activation (Moon ≈ 1 min of birth time)
  hdVarDeg: 0.0005,     // HD colour / tone edge (variables — only a shade, ALGORITHM)
  dashaDays: 1,         // reference date vs. change of the current maha/antar/pratyantar dasha
  // station: |daily motion| below this (deg/day) → direct/retrograde is not decided
  station: { 'Меркурий': 0.08, 'Венера': 0.05, 'Марс': 0.03, 'Юпитер': 0.012, 'Сатурн': 0.008,
    'Уран': 0.004, 'Нептун': 0.003, 'Плутон': 0.003, 'Хирон': 0.003 },
};

const PLANETS = ['Солнце', 'Луна', 'Меркурий', 'Венера', 'Марс', 'Юпитер', 'Сатурн', 'Уран', 'Нептун', 'Плутон'];
const POINTS = ['Лилит', 'Хирон', 'Северный узел', 'Южный узел', 'Селена'];
const NO_NAK = ['Лилит', 'Южный узел', 'Селена'];
const SKY = [['Солнце', SUN], ['Луна', MOON], ['Меркурий', MERCURY], ['Венера', VENUS], ['Марс', MARS], ['Юпитер', JUPITER],
  ['Сатурн', SATURN], ['Уран', URANUS], ['Нептун', NEPTUNE], ['Плутон', PLUTO], ['Хирон', CHIRON], ['Северный узел', TRUE_NODE]];

// ---------------------------------------------------------------- tables
/** Attach the tables: index = parsed v1/index.json; loadChunk(k) → ArrayBuffer | Promise<ArrayBuffer> of chunk_KK.bin. */
export function useTables(index, loadChunk) { setEph(new Ephem(index, loadChunk)); }

/** Browser / Capacitor: tables served next to the app (offline bundle: engine/tools/bundle_tables.cjs). */
export async function useTablesFromUrl(base) {
  if (!base.endsWith('/')) base += '/';
  const get = async (name) => { const r = await fetch(base + name); if (!r.ok) throw new Error('tables: ' + name + ' ' + r.status); return r; };
  const ix = await (await get('index.json')).json();
  useTables(ix, k => get('chunk_' + String(k).padStart(2, '0') + '.bin').then(r => r.arrayBuffer()));
  return ix.version;
}

/** Chunk numbers a chart needs: the birth window (design date −92 days, solar terms ±40 days) and the reference day. */
export function chunksFor(input) {
  const E = eph();
  const { jd, refJd } = moments(input);
  const set = new Set();
  for (const t of [jd - 105, jd, jd + 40, refJd - 2, refJd + 2]) set.add(E.chunkIndex(E.ttFromUT(t)));
  return [...set].sort((a, b) => a - b);
}

/** Load the chunks for this input (await before chartJson when the loader is asynchronous). */
export async function prepare(input) {
  const E = eph();
  for (const k of chunksFor(input)) await E.ensure(E.jd0 + k * E.chunkDays + 1);
}

// ---------------------------------------------------------------- time zones
// Time zones come from engine/data/tz.json (TZDB, embedded at build time), generated from the same tzdata
// as the reference core — never from the device: ICU in phones and browsers is often stale
// (Kazakhstan moved to UTC+5 in 2024; older WebKit still returns +6 — caught by CI 27.09.2026).
export const TZ_VERSION = TZDB.version;
function zoneList(zone) {
  const z = TZDB.zones[zone] || TZDB.zones[TZDB.links[zone]];
  if (!z) throw new Error('unknown time zone: ' + zone);
  return z;
}
function offsetAtUtc(list, utcSec) {              // seconds east of UTC
  let lo = 0, hi = list.length - 1;
  while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (list[mid][0] <= utcSec) lo = mid; else hi = mid - 1; }
  return list[lo][1];
}
/** UTC offset (hours) for a LOCAL civil time; gap and overlap resolve like Python fold=0 (the core). */
export function utcOffsetLocal(zone, y, m, d, hh, mi) {
  const list = zoneList(zone);
  const L = Date.UTC(y, m - 1, d, hh, mi) / 1000;
  const oB = offsetAtUtc(list, L - 129600), oA = offsetAtUtc(list, L + 129600);
  if (oB === oA) return oB / 3600;
  const okB = offsetAtUtc(list, L - oB) === oB, okA = offsetAtUtc(list, L - oA) === oA;
  if (okB) return oB / 3600;                      // unambiguous before, or overlap → first occurrence
  if (okA) return oA / 3600;
  return oB / 3600;                               // gap (time did not exist) → offset before the switch
}

// ---------------------------------------------------------------- helpers
function n360(x) { return ((x % 360) + 360) % 360; }
function edgeDist(lon, width) { const r = n360(lon) % width; return Math.min(r, width - r); }
function parseDate(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
  if (!m) throw new Error('date must be YYYY-MM-DD');
  const t = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  if (t.getUTCFullYear() !== +m[1] || t.getUTCMonth() !== +m[2] - 1 || t.getUTCDate() !== +m[3]) throw new Error('date does not exist: ' + s);
  return [+m[1], +m[2], +m[3]];
}
function parseTime(s) {
  if (s == null || s === '') return null;
  const m = /^(\d{1,2}):(\d{2})$/.exec(s);
  if (!m || +m[1] > 23 || +m[2] > 59) throw new Error('time must be HH:MM');
  return [+m[1], +m[2]];
}
function r4(x) { return +x.toFixed(4); }
function moments(input) {
  const [y, m, d] = parseDate(input.date);
  const t = parseTime(input.time);
  const [hh, mi] = t || [12, 0];
  const pl = input.place || {};
  if (!(isFinite(pl.lat) && isFinite(pl.lon) && typeof pl.tz === 'string')) throw new Error('place {lat, lon, tz} required');
  if (Math.abs(pl.lat) > 90 || Math.abs(pl.lon) > 180) throw new Error('place: lat within ±90, lon within ±180');
  if (y < TZDB.range[0] || y >= TZDB.range[1]) throw new RangeError(`birth year outside the time-zone table ${TZDB.range[0]}–${TZDB.range[1] - 1}`);
  const tz = utcOffsetLocal(pl.tz, y, m, d, hh, mi);
  const ref = input.ref || new Date().toISOString().slice(0, 10);
  const [ry, rm, rd] = parseDate(ref);
  return { y, m, d, hh, mi, unknown: !t, pl, tz, jd: julday(y, m, d, hh + mi / 60 - tz), ref, ry, rm, rd,
    refJd: julday(ry, rm, rd, 0.0) + 0.5 };
}

/**
 * chart.json/1
 * @param {{date:string, time?:string|null, place:{lat:number, lon:number, tz:string}, sex:'m'|'f', ref?:string,
 *          name?:string, name_lang?:'ru'|'uk'}} input
 *   time null/'' = time unknown: noon is used for date-level fields; hour pillar, houses, ASC/MC,
 *   Human Design and Vimshottari (they need the Moon to the minute) are null.
 */
export function chartJson(input) {
  const M = moments(input);
  const { y, m, d, hh, mi, unknown, pl, tz, ref, ry, rm, rd } = M;
  if (input.sex !== 'm' && input.sex !== 'f') throw new Error("sex must be 'm' or 'f'");
  const male = input.sex === 'm';
  const borders = [];

  // ---- bazi ----
  const p = pillarsCore(y, m, d, hh, mi, pl.lon, tz);
  const jd = p.jd;
  const luck = luckCore(p, male, y, m, d, ry, rm, rd);
  if (luck.list.some(x => Math.abs(luck.ageNow - x.a0) < BORDER.luckYears)) borders.push('luck');
  const solarMin = p.solar * 60;
  const toHourEdge = Math.min(...[...Array(13).keys()].map(k => Math.abs(solarMin - (k * 120 - 60))));
  if (!unknown && toHourEdge < BORDER.hourMin) borders.push('hour');
  if (!unknown && p.dayNote) borders.push('day');
  const jieMin = Math.min(jd - luck.jie[0], luck.jie[1] - jd) * 1440;
  if (jieMin < BORDER.jieMin) borders.push('month');

  // ---- natal ----
  const N = natalCore(jd, pl.lat, pl.lon);
  const hs = unknown ? null : N.hs;
  const planets = {};
  for (const n of [...PLANETS, ...POINTS]) {
    const lon = N.lons[n];
    const q = { lon: r4(lon), sign: SIGNS[signIdx(lon)], retro: !!N.retro[n], house: hs ? houseOfLon(hs.cusps, lon) : null };
    if (!NO_NAK.includes(n)) { const k = nakOf(lon, N.ayan); q.nak_index = k.index; q.pada = k.pada; }
    if (n in N.decl) { q.decl = +N.decl[n].toFixed(2); q.oob = Math.abs(N.decl[n]) > N.eps; }
    planets[n] = q;
    if (edgeDist(lon, 30) < BORDER.planetDeg) borders.push('sign:' + n);
    if (!NO_NAK.includes(n) && edgeDist(n360(lon - N.ayan), 360 / 27) < (n === 'Луна' ? BORDER.moonNakDeg : BORDER.planetDeg)) borders.push('nak:' + n);
    if (!NO_NAK.includes(n) && edgeDist(n360(lon - N.ayan), 360 / 108) < (n === 'Луна' ? BORDER.moonNakDeg : BORDER.planetDeg)) borders.push('pada:' + n);
    if (BORDER.station[n] && Math.abs(N.speed[n]) < BORDER.station[n]) borders.push('station:' + n);
    if (n in N.decl && Math.abs(Math.abs(N.decl[n]) - N.eps) < BORDER.planetDeg) borders.push('oob:' + n);
    if (hs && hs.cusps.some(c => Math.abs(((lon - c + 540) % 360) - 180) < BORDER.ascDeg)) borders.push('house:' + n);
  }
  if (hs) {
    if (edgeDist(hs.asc, 30) < BORDER.ascDeg) borders.push('sign:АСЦ');
    if (edgeDist(hs.mc, 30) < BORDER.ascDeg) borders.push('sign:МЦ');
    hs.cusps.forEach((c, i) => { if (edgeDist(c, 30) < BORDER.ascDeg) borders.push('cusp:' + (i + 1)); });
  }
  const natal = { asc: hs ? r4(hs.asc) : null, mc: hs ? r4(hs.mc) : null, cusps: hs ? hs.cusps.map(r4) : null,
    cusp_signs: hs ? hs.cusps.map(c => SIGNS[signIdx(c)]) : null,   // from the exact value (a cusp at 29°59′59″ rounds to 30°)
    ayanamsa: r4(N.ayan), obliquity: r4(N.eps), planets };

  // ---- Human Design, Vimshottari (need the time of birth) ----
  let hd = null, vim = null;
  if (!unknown) {
    hd = humanDesignCore(jd);
    for (const [side, acts] of [['P', hd._raw.pers], ['D', hd._raw.des]]) {
      for (const [b, a] of Object.entries(acts)) {
        const pos = n360(a.lon + 58);
        if (edgeDist(pos, 5.625) < BORDER.hdDeg) borders.push(`hd:gate:${side}:${b}`);
        if ((b === 'Солнце' || b === 'Земля') && edgeDist(pos, 0.9375) < BORDER.hdDeg) borders.push(`hd:line:${side}:${b}`);
        if ((b === 'Солнце' || b === 'Северный узел') && edgeDist(pos, 0.15625 / 6) < BORDER.hdVarDeg) borders.push(`hd:var:${side}:${b}`);
      }
    }
    delete hd._raw;
    vim = vimshottariCore(jd, M.refJd);
    if (vim && vim._edges.some(e => Math.abs(e - M.refJd) < BORDER.dashaDays)) borders.push('dasha');
    if (vim) delete vim._edges;
  }

  // ---- matrix (product canon, chart.py matrix) ----
  const A = red22(d), B = red22(m), C = red22(digits(y)), D = red22(A + B + C), Z = red22(A + B + C + D), R = red22;
  const matrix = {
    A, B, C, D, center: Z,
    code: R(A + D), spirit: R(B + D),
    comfort: { top: R(B + Z), bottom: R(C + Z), left: R(A + Z), right: R(D + Z) },
    money: [R(C + Z), R(R(C + Z) + R(D + Z)), R(R(R(C + Z) + R(D + Z)) + R(C + Z))],
    lineage: { father: [R(A + B), R(C + D)], mother: [R(B + C), R(D + A)] },
  };

  // ---- numerology, tzolkin, feng shui ----
  const numerology = numerologyCore(y, m, d, ry, rm, input.name || null, input.name_lang || null);
  const kin = kinDreamspell(y, m, d);

  // ---- sky on the reference day (noon UTC): "now" chunk ----
  const sky = { date: ref, planets: {} };
  for (const [n, pid] of SKY) {
    const r = calcUT(M.refJd, pid);
    sky.planets[n] = { lon: r4(r[0]), sign: SIGNS[signIdx(r[0])], retro: n === 'Северный узел' ? false : r[3] < 0 };
  }
  sky.moon_nak_index = nakOf(calcUT(M.refJd, MOON)[0], getAyanamsaUT(M.refJd)).index;

  return {
    contract: 'chart.json/1',
    engine: { name: 'js', version: ENGINE_VERSION, core_ref: CORE_REF, tzdata: TZDB.version,
      ephemeris: 'astrogramm-ephem v' + eph().ix.version, source: SOURCE },
    input: { date: input.date, time: unknown ? null : pad2(hh) + ':' + pad2(mi), time_unknown: unknown,
      place: { lat: pl.lat, lon: pl.lon, tz: pl.tz }, utc_offset: tz,
      true_solar: unknown ? null : p.solarTime, eot_min: +p.eot.toFixed(2), day_border: unknown ? null : p.dayNote,
      sex_for_luck: input.sex, ref_date: ref },
    bazi: {
      pillars: { hour: unknown ? null : p.hour, day: p.day, month: p.month, year: p.year },
      dm: p.dm, solar_year: p.solarYear,
      luck: { forward: luck.fwd, start_age: +luck.start.toFixed(2), list: luck.list.map(x => x.gz),
        periods: luck.list.map(x => ({ gz: x.gz, from_age: +x.a0.toFixed(1), from: x.from, to: x.to })),
        current: luck.current >= 0 ? luck.list[luck.current].gz : null },
    },
    natal, human_design: hd, vimshottari: vim,
    matrix, numerology,
    tzolkin: kin,
    gua: guaCore(p.solarYear, !male),
    sky,
    'имя карты': chartName(p.day, kin.kin, natal.planets['Солнце'].sign),   // = core key res['имя карты'] (ext_name.py)
    borders,
  };
}

// ---- city catalog: engine/src/cities.js (data: engine/data/cities.json, attached at run time) ----
// ---------------------------------------------------------------------------------------------
// cities.js — offline city catalog (B1 step 4): GeoNames cities15000 → engine/data/cities.json
// (built by engine/tools/make_cities.py). Search by any Cyrillic or Latin name, ranked by population;
// every city carries its IANA zone, which utcOffsetLocal() resolves from the engine's own tz table.
// Attribution for the UI: CITY_ATTRIBUTION («GeoNames (geonames.org), CC BY 4.0»).
// ---------------------------------------------------------------------------------------------

let CAT = null;

function normName(s) {
  return String(s).toLowerCase().replace(/ё/g, 'е').replace(/[’'ʼ`´]/g, '').replace(/[-‐–—.,()]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

const TRANSLIT = { а: 'a', б: 'b', в: 'v', г: 'g', ґ: 'g', д: 'd', е: 'e', є: 'ye', ж: 'zh', з: 'z', и: 'i', і: 'i', ї: 'yi',
  й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts',
  ч: 'ch', ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya', ў: 'u' };
const translit = s => [...s].map(c => (c in TRANSLIT ? TRANSLIT[c] : c)).join('');
const CYR = /[а-яёіїєґў]/;
const UKR = /[іїєґ]/;
const NOT_RU = /[іїєґўәүөҗңһӳӱјњљћђџѓќѕæ]/;
// Ukrainian cities first among equals (the audience is in Ukraine; «Хар» → Харьков before Харбин): population ×8
const PREFER_CC = 'UA', PREFER_WEIGHT = 8;

/** Attach the catalog (parsed engine/data/cities.json). */
export function useCities(catalog) {
  const idx = catalog.cities.map(c => {
    const names = [c[1], ...(c[7] ? c[7].split('|') : [])];
    return { c, names, keys: names.map(normName) };
  });
  CAT = { cat: catalog, idx };
  return catalog.cities.length;
}

/** Browser / Capacitor: catalog served next to the app (offline bundle: engine/tools/bundle_tables.cjs). */
export async function useCitiesFromUrl(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error('cities: ' + r.status);
  return useCities(await r.json());
}

export const CITY_ATTRIBUTION = 'GeoNames (geonames.org), CC BY 4.0';

function cityOut(e, shown) {
  const [id, name, lat, lon, zi, cc, pop] = e.c;
  const country = CAT.cat.countries[cc] || cc;
  return { id, name: shown || name, name_en: name, country, cc, population: pop, lat, lon, tz: CAT.cat.zones[zi],
    label: `${shown || name}, ${country}` };
}

/** Cities whose name (any Cyrillic or Latin variant) starts with the query; exact names first, then by population. */
export function searchCities(query, limit = 10) {
  if (!CAT) throw new Error('city catalog not attached: call useCities(catalog) first');
  const q = normName(query);
  if (!q) return [];
  const qUkr = UKR.test(q);
  const run = (qq, latinOnly) => {
    const hits = [];
    for (const e of CAT.idx) {
      let best = -1, shown = null;
      e.keys.forEach((k, i) => {
        if (latinOnly && CYR.test(k)) return;
        let s = k === qq && qq.length >= 4 ? 3 : k.startsWith(qq) ? 2 : k.includes(' ' + qq) ? 1 : -1;
        if (s >= 0 && !qUkr && NOT_RU.test(k)) s -= 0.25;       // among equal matches show a Russian-letter alias
        if (s > best) { best = s; shown = e.names[i]; }
      });
      if (best >= 0) hits.push([best, e.c[6] * (e.c[5] === PREFER_CC ? PREFER_WEIGHT : 1), e, shown]);
    }
    return hits;
  };
  let hits = run(q, false);
  if (hits.length < limit && CYR.test(q)) {            // e.g. a town that has no Cyrillic name in GeoNames
    const seen = new Set(hits.map(h => h[2].c[0]));
    for (const h of run(translit(q), true)) if (!seen.has(h[2].c[0])) { h[0] -= 0.5; hits.push(h); }
  }
  hits.sort((a, b) => Math.ceil(b[0]) - Math.ceil(a[0]) || b[1] - a[1]);   // alias penalty never reorders cities
  // Shown name: a Russian query → the Russian name of the city (field 8, engine/tools/city_ru.py), whatever alias matched;
  // a Ukrainian query (і ї є ґ) → the alias the person typed; a Latin query → the GeoNames name.
  return hits.slice(0, limit).map(([, , e, shown]) =>
    cityOut(e, !CYR.test(q) ? null : (!UKR.test(q) && e.c[8]) ? e.c[8]
      : (CYR.test(normName(shown)) && (UKR.test(q) || !NOT_RU.test(normName(shown)))) ? shown : null));   // «Хангџоу» → Hangzhou
}

/** Nearest catalog city (for coordinates typed by hand: its IANA zone). distance_km is great-circle. */
export function nearestCity(lat, lon) {
  if (!CAT) throw new Error('city catalog not attached: call useCities(catalog) first');
  const R = Math.PI / 180, cl = Math.cos(lat * R);
  let best = null, bd = Infinity;
  for (const e of CAT.idx) {
    const dl = (e.c[2] - lat) * R, dn = (e.c[3] - lon) * R;
    const a = Math.sin(dl / 2) ** 2 + cl * Math.cos(e.c[2] * R) * Math.sin(dn / 2) ** 2;
    if (a < bd) { bd = a; best = e; }
  }
  return { ...cityOut(best), distance_km: +(2 * 6371 * Math.asin(Math.sqrt(bd))).toFixed(1) };
}

/** Place object for chartJson() from a search result. */
export function placeOf(city) { return { lat: city.lat, lon: city.lon, tz: city.tz, name: city.label }; }

// ---- day screens from bank/APP_DAY.json: engine/src/day.js ----
// ---------------------------------------------------------------------------------------------
// day.js — day screens from the day bank (B1 step 5, A42): bank/APP_DAY.json, attached at run time with
// useDayBank(). Five layers, one card each:
//   god    day_god_<бог>       stem of the day → ten god for the client's day master (chart.py ten_god)   цикл
//   off    day_off_<建除>       12 officers: day branch − month branch of the day (通书), same for everybody  цикл
//   branch day_branch_<тип>    branch of the day × branch of the client's day pillar                      цикл
//   pd     day_pd_<1–9>        personal day = ЛМ + day (ALGORITHM §6.7)                                    цифры
//   moon   day_moon_house_<1–12> natal house (Placidus) of the Moon at local noon — birth time known     планеты
//          day_moon_sign_<знак>  sign of the Moon at local noon — birth time unknown (A42 P1, ТЗ 2-17 §0)
// Month panel (A42 P1, not part of the day's tier — month scale):
//   pmonth    pmonth_<1–9>     personal month = ЛГ(calendar year) + month → 1–9 (chart.py personal_months)    цифры
//   month_god month_god_<бог>  stem of the month pillar in force at the end of the local day (節) → ten god
//                              for the client's day master (same moment as 建除)                           цикл
// Rotation: day layers line[(JDN + layer offset) mod 3] — changes every day, differs between layers;
//           month panel line[(year·12 + month + layer offset) mod 3] — the same all calendar month.
// Tier of the day (M2): classes of independent sources that share the day's main theme — 3 / 2 / 1 lines.
// The main theme: most classes → most layers → order of the layers above (the client's own layers first).
// Rules fixed by #10 on 29.09.2026 (engine/README.md «Day screens»):
//   • 建除 — month of the day by the solar term in force at the END of the local day (the 節 date is the first
//     day of the new month, as in the almanac); • branch relations — 冲 > 刑 > 害 > 合 > 三合 > same > none
//     (巳申 is 合 and 刑 at once → 刑; 辰辰 午午 酉酉 亥亥 — self-punishment → 刑; 寅寅 and other doubles → same).
// ---------------------------------------------------------------------------------------------

let DAYBANK = null;
const DAY_CLASS = { god: 'цикл', off: 'цикл', branch: 'цикл', pd: 'цифры', moon: 'планеты' };
const DAY_ORDER = ['god', 'branch', 'pd', 'moon', 'off'];
const MONTH_CLASS = { pmonth: 'цифры', month_god: 'цикл' };
const MONTH_ORDER = ['pmonth', 'month_god'];
const GOD_KEY = { 'Опора': 'friend', 'Соперник': 'rob_wealth', 'Выход-творчество': 'eating_god', 'Выход-бунт': 'hurting_officer',
  'Деньги косвенные': 'indirect_wealth', 'Деньги прямые': 'direct_wealth', 'Пресс жёсткий': 'seven_killings',
  'Долг и власть': 'direct_officer', 'Ресурс нестандартный': 'indirect_resource', 'Ресурс тёплый': 'direct_resource' };
const OFF_KEY = ['jian', 'chu', 'man', 'ping', 'ding', 'zhi', 'po', 'wei', 'cheng', 'shou', 'kai', 'bi'];
const MOON_KEY = ['aries', 'taurus', 'gemini', 'cancer', 'leo', 'virgo', 'libra', 'scorpio', 'sagittarius', 'capricorn', 'aquarius', 'pisces'];
const LIUHE = { '子': '丑', '丑': '子', '寅': '亥', '亥': '寅', '卯': '戌', '戌': '卯', '辰': '酉', '酉': '辰', '巳': '申', '申': '巳', '午': '未', '未': '午' };
const LIUHAI = { '子': '未', '未': '子', '丑': '午', '午': '丑', '寅': '巳', '巳': '寅', '卯': '辰', '辰': '卯', '申': '亥', '亥': '申', '酉': '戌', '戌': '酉' };
const XING_SETS = ['寅巳申', '丑戌未', '子卯'];
const SELF_XING = '辰午酉亥';
const TRIOS = ['申子辰', '亥卯未', '寅午戌', '巳酉丑'];

function tenGodName(dm, g) {                      // chart.py ten_god
  const a = GAN.indexOf(dm), b = GAN.indexOf(g), ea = a >> 1, eb = b >> 1, same = a % 2 === b % 2;
  if (ea === eb) return same ? 'Опора' : 'Соперник';
  if ((ea + 1) % 5 === eb) return same ? 'Выход-творчество' : 'Выход-бунт';
  if ((ea + 2) % 5 === eb) return same ? 'Деньги косвенные' : 'Деньги прямые';
  if ((eb + 2) % 5 === ea) return same ? 'Пресс жёсткий' : 'Долг и власть';
  return same ? 'Ресурс нестандартный' : 'Ресурс тёплый';
}

function branchRelation(dayZ, birthZ) {
  if (ZHI.indexOf(dayZ) === (ZHI.indexOf(birthZ) + 6) % 12) return 'chong';
  if (dayZ === birthZ) return SELF_XING.includes(dayZ) ? 'xing' : 'same';
  if (XING_SETS.some(s => s.includes(dayZ) && s.includes(birthZ))) return 'xing';
  if (LIUHAI[birthZ] === dayZ) return 'hai';
  if (LIUHE[birthZ] === dayZ) return 'he';
  if (TRIOS.some(t => t.includes(dayZ) && t.includes(birthZ))) return 'sanhe';
  return 'none';
}

/** Attach the day bank (parsed bank/APP_DAY.json). */
export function useDayBank(bank) {
  if (!bank || bank.bank !== 'app_day' || !bank.cards) throw new Error('not an APP_DAY bank');
  DAYBANK = bank.cards;
  return Object.keys(DAYBANK).length;
}
export async function useDayBankFromUrl(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error('day bank: ' + r.status);
  return useDayBank(await r.json());
}

/** Chunk of the tables a given civil date needs (Moon at noon, Sun at the end of the day). */
export async function prepareDate(dateISO) {
  const [y, m, d] = parseDate(dateISO);
  const E = eph();
  await E.ensure(E.ttFromUT(julday(y, m, d, 0)));
  await E.ensure(E.ttFromUT(julday(y, m, d, 24)));
}

function birthOf(src) {
  if (src && src.contract === 'chart.json/1') return { dm: src.bazi.dm, dayZ: src.bazi.pillars.day[1], date: src.input.date,
    tz: src.input.place.tz, cusps: src.input.time_unknown ? null : (src.natal && src.natal.cusps) || null };
  const M = moments(src);
  const p = pillarsCore(M.y, M.m, M.d, M.hh, M.mi, M.pl.lon, M.tz);
  return { dm: p.dm, dayZ: p.day[1], date: src.date, tz: M.pl.tz, cusps: M.unknown ? null : housesP(M.jd, M.pl.lat, M.pl.lon).cusps };
}

function dayLayers(B, dateISO, tzName) {
  const [y, m, d] = parseDate(dateISO);
  const J = jdn(y, m, d);
  const idx = pmod(J + 49, 60), dayG = GAN[idx % 10], dayZ = ZHI[idx % 12];
  const off0 = utcOffsetLocal(tzName, y, m, d, 12, 0);
  // month branch: solar term in force at the end of the local day
  const offE = utcOffsetLocal(tzName, y, m, d, 23, 59);
  const Lend = calcUT(julday(y, m, d, 24 - offE) - 1e-7, SUN)[0];
  const monthZ = ZHI[(Math.floor(pmod(Lend - 315, 360) / 30) + 2) % 12];
  const solarYear = (m <= 2 && !(315 <= Lend && Lend < 360)) ? y - 1 : y;          // year pillar changes at 立春
  const yearG = GAN[pmod(solarYear - 4, 10)];
  const monthG = GAN[(GAN.indexOf(yearG) * 2 + pmod(ZHI.indexOf(monthZ) - 2, 12) + 2) % 10];
  const off = pmod(ZHI.indexOf(dayZ) - ZHI.indexOf(monthZ), 12);
  const moonLon = calcUT(julday(y, m, d, 12 - off0), MOON)[0];
  const [by, bm, bd] = parseDate(B.date);
  const py = redMaster(digits(bd) + digits(bm) + digits(y));
  const pm = red9(py + m);
  const pd = red9(pm + d);
  const house = B.cusps ? houseOfLon(B.cusps, n360(moonLon)) : null;
  return { J, gz: dayG + dayZ, monthZ, monthGz: monthG + monthZ, keys: {
    god: 'day_god_' + GOD_KEY[tenGodName(B.dm, dayG)],
    off: 'day_off_' + OFF_KEY[off],
    branch: 'day_branch_' + branchRelation(dayZ, B.dayZ),
    pd: 'day_pd_' + pd,
    moon: house ? 'day_moon_house_' + house : 'day_moon_sign_' + MOON_KEY[signIdx(moonLon)],
  }, month: { pmonth: 'pmonth_' + pm, month_god: 'month_god_' + GOD_KEY[tenGodName(B.dm, monthG)] },
  pd, pm, moonSign: SIGNS[signIdx(moonLon)], moonHouse: house };
}

function dayTier(keys) {
  const byTheme = {};
  DAY_ORDER.forEach((layer, i) => {
    const t = DAYBANK[keys[layer]].theme;
    const e = byTheme[t] || (byTheme[t] = { theme: t, classes: new Set(), layers: [], first: i });
    e.classes.add(DAY_CLASS[layer]); e.layers.push(layer);
  });
  const best = Object.values(byTheme).sort((a, b) => b.classes.size - a.classes.size || b.layers.length - a.layers.length || a.first - b.first)[0];
  return { theme: best.theme, tier: best.classes.size, layers: best.layers, classes: [...best.classes] };
}

/**
 * Day screen for one civil date. src = chart.json/1 (from chartJson) or the same input chartJson takes.
 * opts.tz — zone of the day (the phone's zone; default: birth zone). Needs useDayBank() and the date's chunk.
 */
export function dayJson(src, dateISO, opts = {}) {
  if (!DAYBANK) throw new Error('day bank not attached: call useDayBank(bank) first');
  const B = birthOf(src);
  const L = dayLayers(B, dateISO, opts.tz || B.tz);
  const T = dayTier(L.keys);
  const layers = DAY_ORDER.map((layer, i) => {
    const key = L.keys[layer], c = DAYBANK[key];
    return { layer, class: DAY_CLASS[layer], key, theme: c.theme, title: c.title, line: c.line[pmod(L.J + i, c.line.length)],
      do: c.do, dont: c.dont, more: c.more, in_theme: c.theme === T.theme };
  });
  const lead = layers.find(x => x.layer === T.layers[0]);
  const month = MONTH_ORDER.map((layer, i) => {
    const key = L.month[layer], c = DAYBANK[key];
    if (!c) throw new Error('day bank has no card ' + key + ' (A42 P1 missing?)');
    return { layer, class: MONTH_CLASS[layer], key, theme: c.theme, title: c.title,
      line: c.line[pmod((+dateISO.slice(0, 4)) * 12 + (+dateISO.slice(5, 7)) + i, c.line.length)], do: c.do, dont: c.dont, more: c.more };
  });
  return { date: dateISO, gz: L.gz, personal_day: L.pd, moon_sign: L.moonSign, moon_house: L.moonHouse,
    theme: T.theme, tier: T.tier, tier_classes: T.classes, lead: lead.key, line: lead.line, layers,
    month: { gz: L.monthGz, personal_month: L.pm, layers: month } };
}

/**
 * Month panel for v12 (A42 P1): { cards: [pmonth_, month_god_], gz, personal_month, line: [i, i] }.
 * The month god follows the month pillar of the given date (it changes around the 4th–8th, at 節).
 */
export function monthPick(src, dateKey, opts = {}) {
  const d = dayJson(src, dateKey, opts);
  return { cards: d.month.layers.map(l => l.key), gz: d.month.gz, personal_month: d.month.personal_month,
    line: d.month.layers.map(l => DAYBANK[l.key].line.indexOf(l.line)) };
}

/**
 * v12 contract (product/DESIGN-SYSTEM.md §9): the engine picks, the page shows its own copy of APP_DAY.
 * → { cards: [APP_DAY keys, the day's theme first (main first), then the other layers], main, line: 0..2, tier: 1..3 }.
 * Throws when a table chunk is missing — the page calls prepare(input) and redraws.
 */
export function dayPick(src, dateKey, opts = {}) {
  const d = dayJson(src, dateKey, opts);
  const main = d.layers.find(l => l.key === d.lead);
  const cards = [main, ...d.layers.filter(l => l.in_theme && l !== main), ...d.layers.filter(l => !l.in_theme)].map(l => l.key);
  return { cards, main: main.key, line: DAYBANK[main.key].line.indexOf(main.line), tier: d.tier, theme: d.theme };
}

/** Calendar month: one cell per day — theme + tier (texts differ between charts through god, branch and pd). */
export function calendarJson(src, year, month, opts = {}) {
  const n = new Date(Date.UTC(year, month, 0)).getUTCDate();
  const out = [];
  for (let d = 1; d <= n; d++) {
    const iso = `${year}-${pad2(month)}-${pad2(d)}`;
    const x = dayJson(src, iso, opts);
    out.push({ date: iso, gz: x.gz, theme: x.theme, tier: x.tier, line: x.line });
  }
  return out;
}

// ---- BaZi D10: strength, useful elements, day layer: engine/src/d10.js ----
// ---------------------------------------------------------------------------------------------
// d10.js — BaZi D10 day-level functions (#22): port of skills/astrogramm-core/chart.py, section "бацзы D10"
// (season_state, dm_strength, balance_units, tiaohou, useful_elements without the format check, branch_vs, cs_stage).
// d10Json(src)               → { strength, useful }   (time unknown → no hour pillar, total 480 instead of 620)
// dayD10(src, dateISO, opts) → { gz, stage, taisui, element }   (same day pillar / zone / 立春 rule as dayJson)
